package com.bank.unbounded.service;

import java.util.logging.Logger;

// Maximizes return within a budget allowing unlimited units of each instrument.
public class UnboundedPortfolioService {
    private static final Logger log = Logger.getLogger(UnboundedPortfolioService.class.getName());

    public int maxReturn(int[] costs, int[] returns, int budget) {
        int[] dp = new int[budget + 1];
        for (int i = 0; i < costs.length; i++) {
            // Sweep capacity LOW to HIGH so each instrument can repeat.
            for (int c = costs[i]; c <= budget; c++) {
                dp[c] = Math.max(dp[c], returns[i] + dp[c - costs[i]]);
            }
        }
        log.info(() -> "Max return (with repetition) = " + dp[budget]);
        return dp[budget];
    }
}
