package com.bank.unbounded;

import com.bank.unbounded.service.UnboundedPortfolioService;
import java.util.logging.Logger;

public class UnboundedPortfolioApplication {
    private static final Logger log = Logger.getLogger(UnboundedPortfolioApplication.class.getName());

    public static void main(String[] args) {
        UnboundedPortfolioService service = new UnboundedPortfolioService();
        int[] costs = {1, 3, 4};        // unit costs (in lakhs)
        int[] returns = {15, 50, 60};   // unit returns (in thousands)
        int budget = 8;                 // Rajesh's budget (in lakhs)
        int best = service.maxReturn(costs, returns, budget);
        log.info("Best return within budget " + budget + " lakh (repeats allowed): " + best);
    }
}
